import React, { useRef, useEffect, useState, useCallback } from 'react';
import { DigoAsset } from '@digo-org/digo-api';
import * as d3 from 'd3';

interface CityDataPoint {
  year: string;
  price: number;
  ratio: number;
  income: number;
}

interface TooltipState {
  visible: boolean;
  x: number;
  y: number;
  city: string;
  year: string;
  price: number;
  ratio: number;
  income: number;
  color: string;
}

function ConnectedScatterplot({
  instances,
  globalParameters,
  timeArray,
}: {
  instances: any[];
  globalParameters: Record<string, any>;
  timeArray: string[];
}) {
  const svgRef = useRef<SVGSVGElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [dimensions, setDimensions] = useState({ width: 800, height: 500 });
  const [tooltip, setTooltip] = useState<TooltipState>({
    visible: false,
    x: 0,
    y: 0,
    city: '',
    year: '',
    price: 0,
    ratio: 0,
    income: 0,
    color: '',
  });

  const backgroundColor = (globalParameters['background-color'] as string) || '#f8f9fa';
  const dotRadius = (globalParameters['dot-radius'] as number) || 5;
  const lineWidth = (globalParameters['line-width'] as number) || 2;
  const showLabels = globalParameters['show-labels'] !== undefined ? (globalParameters['show-labels'] as boolean) : true;
  const title = (globalParameters['title'] as string) || 'Housing Prices vs Income Ratio';
  const legendTextColor = (globalParameters['legend-text-color'] as string) || '#444';
  const legendTextSize = (globalParameters['legend-text-size'] as number) || 11;

  const margin = { top: 60, right: 160, bottom: 60, left: 70 };

  useEffect(() => {
    const handleResize = () => {
      if (containerRef.current) {
        const rect = containerRef.current.getBoundingClientRect();
        setDimensions({ width: rect.width, height: rect.height });
      }
    };
    handleResize();
    const observer = new ResizeObserver(handleResize);
    if (containerRef.current) observer.observe(containerRef.current);
    return () => observer.disconnect();
  }, []);

  const drawChart = useCallback(() => {
    if (!svgRef.current || !instances || instances.length === 0) return;

    const svg = d3.select(svgRef.current);
    svg.selectAll('*').remove();

    const width = dimensions.width - margin.left - margin.right;
    const height = dimensions.height - margin.top - margin.bottom;

    if (width <= 0 || height <= 0) return;

    const g = svg
      .append('g')
      .attr('transform', `translate(${margin.left},${margin.top})`);

    const fallbackColors = d3.scaleOrdinal(d3.schemeTableau10);

    const citiesData: { name: string; color: string; points: CityDataPoint[] }[] = [];

    let allPrices: number[] = [];
    let allRatios: number[] = [];

    instances.forEach((instance: any, idx: number) => {
      const cityName = (instance['label'] as string) || `City ${idx + 1}`;
      const prices = (instance['median_home_price'] as number[]) || [];
      const ratios = (instance['price_to_income_ratio'] as number[]) || [];
      const incomes = (instance['median_income'] as number[]) || [];
      const color = (instance['line-color'] as string) || fallbackColors(String(idx));

      const points: CityDataPoint[] = [];
      const len = Math.min(prices.length, ratios.length, timeArray.length || Infinity);
      for (let i = 0; i < len; i++) {
        if (prices[i] != null && ratios[i] != null) {
          points.push({
            year: timeArray[i] || String(i),
            price: prices[i],
            ratio: ratios[i],
            income: incomes[i] || 0,
          });
          allPrices.push(prices[i]);
          allRatios.push(ratios[i]);
        }
      }

      if (points.length > 0) {
        citiesData.push({ name: cityName, color, points });
      }
    });

    if (citiesData.length === 0) return;

    const xExtent = d3.extent(allPrices) as [number, number];
    const yExtent = d3.extent(allRatios) as [number, number];

    const xPadding = (xExtent[1] - xExtent[0]) * 0.08 || 10;
    const yPadding = (yExtent[1] - yExtent[0]) * 0.08 || 0.5;

    const xScale = d3
      .scaleLinear()
      .domain([xExtent[0] - xPadding, xExtent[1] + xPadding])
      .range([0, width]);

    const yScale = d3
      .scaleLinear()
      .domain([yExtent[0] - yPadding, yExtent[1] + yPadding])
      .range([height, 0]);

    // Grid lines
    g.append('g')
      .attr('class', 'grid-x')
      .attr('transform', `translate(0,${height})`)
      .call(
        d3.axisBottom(xScale).tickSize(-height).tickFormat(() => '')
      )
      .selectAll('line')
      .attr('stroke', '#e0e0e0')
      .attr('stroke-dasharray', '3,3');

    g.append('g')
      .attr('class', 'grid-y')
      .call(
        d3.axisLeft(yScale).tickSize(-width).tickFormat(() => '')
      )
      .selectAll('line')
      .attr('stroke', '#e0e0e0')
      .attr('stroke-dasharray', '3,3');

    g.selectAll('.grid-x .domain, .grid-y .domain').remove();

    // X axis
    g.append('g')
      .attr('transform', `translate(0,${height})`)
      .call(d3.axisBottom(xScale).ticks(8).tickFormat(d => `$${d3.format(',.0f')(d as number)}K`))
      .selectAll('text')
      .attr('fill', '#555')
      .style('font-size', '11px');

    g.append('text')
      .attr('x', width / 2)
      .attr('y', height + 45)
      .attr('text-anchor', 'middle')
      .attr('fill', '#444')
      .style('font-size', '13px')
      .style('font-weight', '500')
      .text('Median Home Price (thousands USD)');

    // Y axis
    g.append('g')
      .call(d3.axisLeft(yScale).ticks(6).tickFormat(d => `${d3.format('.1f')(d as number)}x`))
      .selectAll('text')
      .attr('fill', '#555')
      .style('font-size', '11px');

    g.append('text')
      .attr('transform', 'rotate(-90)')
      .attr('x', -height / 2)
      .attr('y', -50)
      .attr('text-anchor', 'middle')
      .attr('fill', '#444')
      .style('font-size', '13px')
      .style('font-weight', '500')
      .text('Price-to-Income Ratio');

    // Title
    svg
      .append('text')
      .attr('x', dimensions.width / 2)
      .attr('y', 30)
      .attr('text-anchor', 'middle')
      .attr('fill', '#222')
      .style('font-size', '18px')
      .style('font-weight', '700')
      .text(title);

    // Draw paths and dots per city
    const line = d3
      .line<CityDataPoint>()
      .x(d => xScale(d.price))
      .y(d => yScale(d.ratio))
      .curve(d3.curveMonotoneX);

    citiesData.forEach((city) => {
      // Draw the path
      const path = g
        .append('path')
        .datum(city.points)
        .attr('fill', 'none')
        .attr('stroke', city.color)
        .attr('stroke-width', lineWidth)
        .attr('stroke-opacity', 0.7)
        .attr('d', line);

      // Animate path drawing
      const totalLength = (path.node() as SVGPathElement)?.getTotalLength() || 0;
      path
        .attr('stroke-dasharray', `${totalLength} ${totalLength}`)
        .attr('stroke-dashoffset', totalLength)
        .transition()
        .duration(2000)
        .ease(d3.easeCubicInOut)
        .attr('stroke-dashoffset', 0);

      // Draw dots
      g.selectAll(`.dot-${city.name.replace(/\s/g, '-')}`)
        .data(city.points)
        .enter()
        .append('circle')
        .attr('cx', d => xScale(d.price))
        .attr('cy', d => yScale(d.ratio))
        .attr('r', 0)
        .attr('fill', city.color)
        .attr('stroke', '#fff')
        .attr('stroke-width', 1.5)
        .style('cursor', 'pointer')
        .on('mouseenter', function (event: MouseEvent, d: CityDataPoint) {
          d3.select(this)
            .transition()
            .duration(150)
            .attr('r', dotRadius * 1.6);
          const svgRect = svgRef.current?.getBoundingClientRect();
          if (svgRect) {
            setTooltip({
              visible: true,
              x: event.clientX - svgRect.left,
              y: event.clientY - svgRect.top - 10,
              city: city.name,
              year: d.year,
              price: d.price,
              ratio: d.ratio,
              income: d.income,
              color: city.color,
            });
          }
        })
        .on('mouseleave', function () {
          d3.select(this)
            .transition()
            .duration(150)
            .attr('r', dotRadius);
          setTooltip(prev => ({ ...prev, visible: false }));
        })
        .transition()
        .delay((_, i) => (i / city.points.length) * 2000)
        .duration(300)
        .attr('r', dotRadius);

      // Year labels on first and last points
      if (showLabels && city.points.length > 0) {
        const firstPt = city.points[0];
        const lastPt = city.points[city.points.length - 1];

        const addLabel = (pt: CityDataPoint, anchor: string, dx: number) => {
          g.append('text')
            .attr('x', xScale(pt.price))
            .attr('y', yScale(pt.ratio))
            .attr('dx', dx)
            .attr('dy', -dotRadius - 4)
            .attr('text-anchor', anchor)
            .attr('fill', city.color)
            .style('font-size', '10px')
            .style('font-weight', '600')
            .style('opacity', 0)
            .text(pt.year)
            .transition()
            .delay(2000)
            .duration(500)
            .style('opacity', 1);
        };

        addLabel(firstPt, 'end', -4);
        if (city.points.length > 1) {
          addLabel(lastPt, 'start', 4);
        }
      }
    });

    // Legend
    const legend = svg
      .append('g')
      .attr('transform', `translate(${dimensions.width - margin.right + 20}, ${margin.top})`);

    legend
      .append('text')
      .attr('x', 0)
      .attr('y', 0)
      .attr('fill', legendTextColor)
      .style('font-size', `${legendTextSize + 1}px`)
      .style('font-weight', '700')
      .text('Cities');

    citiesData.forEach((city, i) => {
      const row = legend.append('g').attr('transform', `translate(0, ${20 + i * 24})`);

      row
        .append('line')
        .attr('x1', 0)
        .attr('y1', 0)
        .attr('x2', 20)
        .attr('y2', 0)
        .attr('stroke', city.color)
        .attr('stroke-width', lineWidth);

      row
        .append('circle')
        .attr('cx', 10)
        .attr('cy', 0)
        .attr('r', dotRadius * 0.7)
        .attr('fill', city.color)
        .attr('stroke', '#fff')
        .attr('stroke-width', 1);

      row
        .append('text')
        .attr('x', 28)
        .attr('y', 4)
        .attr('fill', legendTextColor)
        .style('font-size', `${legendTextSize}px`)
        .text(city.name);
    });
  }, [instances, globalParameters, timeArray, dimensions, dotRadius, lineWidth, showLabels, title, legendTextColor, legendTextSize]);

  useEffect(() => {
    drawChart();
  }, [drawChart]);

  return (
    <div
      ref={containerRef}
      style={{
        width: '100%',
        height: '100%',
        backgroundColor,
        position: 'relative',
        fontFamily: "'Inter', 'Segoe UI', system-ui, -apple-system, sans-serif",
        overflow: 'hidden',
      }}
    >
      <svg
        ref={svgRef}
        width={dimensions.width}
        height={dimensions.height}
        style={{ display: 'block' }}
      />
      {tooltip.visible && (
        <div
          style={{
            position: 'absolute',
            left: tooltip.x,
            top: tooltip.y,
            transform: 'translate(-50%, -100%)',
            background: '#fff',
            border: `2px solid ${tooltip.color}`,
            borderRadius: '8px',
            padding: '10px 14px',
            boxShadow: '0 4px 16px rgba(0,0,0,0.12)',
            pointerEvents: 'none',
            zIndex: 10,
            fontSize: '12px',
            lineHeight: '1.6',
            whiteSpace: 'nowrap',
          }}
        >
          <div style={{ fontWeight: 700, color: tooltip.color, marginBottom: 2 }}>
            {tooltip.city}
          </div>
          <div style={{ color: '#555' }}>
            <strong>Year:</strong> {tooltip.year}
          </div>
          <div style={{ color: '#555' }}>
            <strong>Price:</strong> ${d3.format(',.0f')(tooltip.price)}K
          </div>
          <div style={{ color: '#555' }}>
            <strong>Ratio:</strong> {d3.format('.2f')(tooltip.ratio)}x
          </div>
          {tooltip.income > 0 && (
            <div style={{ color: '#555' }}>
              <strong>Income:</strong> ${d3.format(',.0f')(tooltip.income)}K
            </div>
          )}
        </div>
      )}
    </div>
  );
}

export class Asset extends DigoAsset {
  constructor() {
    super();
  }

  render() {
    return (
      <ConnectedScatterplot
        instances={this.instances || []}
        globalParameters={this.globalParameters || {}}
        timeArray={this.timeArray || []}
      />
    );
  }
}

